from model import *
c=C(9,'载荷、燃油与地面服务详细设计','第二篇  分模块详细设计')
S(c,'载荷对象与舱位分配',
P('总量计划与空间分布','''本地航班保存人数、单人质量、平均行李质量和额外货物四个总量参数；原生载重页进一步把旅客分布到十个客舱区域，把行李和货物分布到四个货舱。总量回答“装多少”，舱位分布回答“装在哪里”，两者具有不同的数据粒度。

A339Payload 读取 cabinInfo.seatMap 与 cargoMap。客舱配置提供容量和变量名称，货舱配置提供最大质量、变量名称及进度条尺寸。页面依据配置构造图形，不把每个舱位的几何与容量重复写入航班对象。

当前 Flight 没有座位分布和重心字段。因此导出本地航班文件能够恢复总量计划，但不能作为完整座位图或配载平衡表的替代文件。''',diagram=D('entity','总量与分布的两层模型',[['Flight','pax / paxKg','bagKg / freightKg','质量合计'],['客舱配置','10 个区域','容量与变量名','座位位图'],['货舱配置','4 个装载区域','容量与变量名','当前及目标质量']],[(0,1,'总人数分配至客舱'),(0,2,'行李和货物分配至货舱')]),table=T('数据层|表达方式|使用目的','航班计划|人数及质量参数|计算与文件交换\n客舱分布|SeatFlags 集合|图形座位选择\n货舱分布|质量数组|舱位装载显示\n重量重心|宿主变量|原生载重图表')),
P('座位位图与目标集合','''每个客舱区域由一个 SeatFlags 对象描述占用状态。当前座位和目标座位分别读取不带后缀与带 _DESIRED 后缀的变量。totalPax 与 totalPaxDesired 对各区域已填充座位数求和，因此图中的座位变化能够反映为人数变化。

自动分配人数时，setTargetPax 从最后一个区域向前处理，按区域容量占总容量的比例计算目标人数，并用区域容量截断。第一个区域接收剩余人数，使取整余数有明确归属。chooseDesiredSeats 只增减与现有目标的差额。

比例经过源码中的精度处理，并非精确的实数比例。文件中还保留了快速连续点击座位可能计算不一致的注释；本地总量模型因此不依赖连续点击的中间状态推算性能重量。''',diagram=D('lanes','当前与目标座位是两组独立集合',[['当前','区域位图','人数求和','实际显示'],['目标','区域目标位图','目标人数求和','装载目标'],['分配','总人数','按容量比例','首区收余数']]),table=T('对象|主要方法|含义','SeatFlags|getTotalFilledSeats|区域已占用数量\n目标位图|fillEmptySeats|增加目标座位\n目标位图|emptyFilledSeats|减少目标座位\n单座位|toggleSeatId|反转指定座位状态')),
P('行李货物的分配规则','''setTargetCargo 先把旅客数量乘以平均行李质量，再加上取整后的额外货物。合计不超过配置中的 maxCargo。各货舱按自身容量与总容量的比例分配质量，最后把剩余量交给第一个货舱，减少逐舱取整造成的总量偏差。

单击货舱进度条时，页面将鼠标在条内的位置除以进度条宽度，再截断到 0～1。这个比例乘以该舱容量后写入目标变量。正在登机或 GSX 正在执行时，此类修改被拦截。

座位增减会改变行李质量。页面先从旧货物合计中减去旧行李估计，保留额外货物，再按新人数重新分配。因此“货舱合计”与 Flight.freightKg 不是同一字段，前者通常已经包含行李。''',diagram=D('formula','货舱目标计算',[['行李质量','B = N × b'],['可分配总量','C = min(B + round(F), Cmax)'],['舱位比例','Ci = round(C × capacity_i / Cmax)']]),table=T('样例项|数值|解释','旅客数|250 人|N\n平均行李|24 kg/人|b\n额外货物|2000 kg|F\n货舱总量|8000 kg|6000 kg 行李 + 2000 kg 货物\n人体质量|20000 kg|不计入货舱总量')),
P('总重反推与重心显示','''原生页面也允许从 ZFW 或 GW 反推目标。processZfw 从新零油重中减去空重，先按每人及行李的合计质量估算人数，再把剩余非负质量作为额外货物。processGw 还扣除当前 GW 与 ZFW 之差所表示的燃油质量。

人数需要取整和容量截断，所以反推不是连续、唯一的配载优化过程。相同总重量可以对应不同的人货组合。页面采用“先旅客、后货物”的确定性规则，方便快速形成初始目标。

ZFW/GW 重心百分比直接从宿主变量读取，并非本地 Flight 根据力臂计算所得。浏览器演示不能据此声称已有完整 A330 载重平衡内核。''',diagram=D('components','质量反推与重心读取的不同路径',['输入 ZFW / GW','扣空重和燃油','估算人数及货物','宿主 CG 变量','载重图表'],[(0,1,'质量预算'),(1,2,'人数优先'),(2,4,'目标质量'),(3,4,'读取 %MAC')]),table=T('入口|使用的质量预算|输出性质','输入 ZFW|ZFW − 空重|初始人货目标\n输入 GW|GW − 空重 − 当前燃油|初始人货目标\n重心图|宿主 CG 数据|读取显示\n本地工作台|已知人数与货物正向合计|计划重量')) ,refs=['EFB','L-F','L-S','GND'])
S(c,'燃油模型与目标分配',
P('质量、体积与显示单位','''航班计划以 kg 保存燃油，原生油箱变量以 US gallon 表示体积，页面又可以按 kg 或 lb 显示。A330Fuel 通过 FUEL WEIGHT PER GALLON 取得密度，并结合显示单位转换因子完成换算。密度和单位因子应视为两个不同概念。

本地宿主提供 3.039 kg/US gal 的演示密度。改变显示单位不应修改计划油量，也不能把整数显示值当作无损存储值。油箱读数存在取整及中心油箱的显示补偿，计算模型仍使用保存的 kg 数值。

容量来自机型配置与宿主变量。总容量等于两个外侧油箱、两个内侧油箱与中央油箱之和；本书涉及的是该版本页面的数据模型。''',diagram=D('formula','燃油质量与体积换算',[['体积 → 质量','m_kg = V_USgal × density_kg/USgal'],['质量 → 体积','V_USgal = m_kg / density_kg/USgal'],['质量显示','m_lb = m_kg / 0.45359237']]),table=T('油箱|单个容量 / US gal|数量','外侧|964|2\n内侧|11095|2\n中央|12625|1\n总量|36743|五个显示区域')),
P('原生页面的分级分配','''setDesiredFuel 接收体积总量，按四个阶段分配目标。先向左右内侧各分配最多 1480 US gal，再向左右外侧各分配最多 964 US gal；随后补足左右内侧至各 11095 US gal，最后把剩余量送入中央油箱，上限 12625 US gal。

每个对称阶段采用剩余量的一半，并用该阶段容量限制。因此在总量不足以完成某阶段时，两侧仍然对称；若剩余量已耗尽，后续油箱目标显式置零，防止沿用上一次较大目标的残值。

这套目标分配来自选定源码。源码中的 FCOM 注释是其来源声明，不能替代独立原始资料核对。实现超过容量时输出警告，不能据此推导额外油箱或自动消纳机制。''',diagram=D('pipeline','原生燃油页 setDesiredFuel 分配顺序',['输入总体积','内侧各至 1480','外侧各至 964','内侧各补至 11095','中央至 12625','发布各箱目标']),table=T('累计阈值|达到后的状态|下一阶段','2960 US gal|内侧第一阶段完成|分配外侧\n4888 US gal|外侧填充完成|补足内侧\n24118 US gal|左右机翼目标满|分配中央\n36743 US gal|全部容量达到|超量不再分配')),
P('30 吨计划的分配示例','''30000 kg 按本地密度换算，约为 9871.668 US gal。第一阶段使用 2960，第二阶段使用 1928，剩余 4983.668 继续均分到两个内侧区域，因此每个内侧约为 3971.834，两个外侧各 964，中央为零。

本地确认函数为启动显示写入样例当前油量时，采用先外侧、再内侧、最后中央的简化顺序。30 吨例子最终恰好与原生目标一致，但低油量时可能不同。例如总体积 2000 US gal，原生目标全部进入内侧，启动样例则先填外侧。

因此必须把“初始化当前值”与“用户调整目标值”区分开。后续接入真实后端时，当前油量应来自后端快照，页面只发送目标和动作。''',table=T('区域|30 吨原生目标 / US gal|2000 US gal 原生目标','左外侧|964|0\n右外侧|964|0\n左内侧|3971.834|1000\n右内侧|3971.834|1000\n中央|0|0'),diagram=D('lanes','当前值来源与目标值来源',[['当前值','启动样例或后端','油箱当前变量','进度填充'],['目标值','用户或确认计划','分级分配函数','目标标记']])),
P('总目标输入与时间估计','''数字框先解析整数质量，再换算成体积并调用分配函数；滑块把百分比换算为总质量，再进入相同路径。两种控件共享目标更新逻辑，避免滑块和数字框分别维护油箱分配算法。

预计时间根据机翼与中央油箱的目标差分别估算，再取二者最大值。机翼全量基准时间为 1300 秒，中央为 1200 秒；快速模式再除以 5，即时模式返回零。该估计体现两组区域并行处理的界面模型。

“完成”比较还使用体积容差，isFuelEqualTo 的差值阈值为 10，其调用上下文是 US gal。该阈值不应写成 10 kg，也不等同于加油设备的测量精度。''',diagram=D('formula','加油时间的页面估计模型',[['机翼部分','tW = abs(VW_target − VW_current) / 24118 × 1300'],['中央部分','tC = abs(VC_target − VC_current) / 12625 × 1200'],['并行估计','t = max(tW, tC)；FAST 时 t / 5']]),table=T('模式|配置值|显示估计','真实|0|使用基准时间\n快速|1|基准时间除以 5\n即时|2|显示 0\n当前与目标相同|任意|显示 0')) ,refs=['EFB','L-S','L-H','GND'])
S(c,'地面服务状态与操作协议',
P('服务可用性的组合条件','''A330Services 以在地面、飞机静止、未连接推出三个条件共同判断一般地服是否可用。页面同时读取舱门、外接电源和服务设备变量，并将按钮状态保存在 groundServicePage。动作许可与按钮表现由不同输入共同决定。

地服图使用 A330 机体轮廓和位置化按钮。按钮按服务与舱门关系分组，减少用户把货舱操作与客舱操作混淆。隐藏状态不渲染，禁用状态降低透明度并取消动作，活动与呼叫状态采用不同色彩。

颜色用于概括状态，文字与图标仍提供识别信息。软件设计不能只依赖绿色或橙色表达含义，否则黑白打印和色觉差异会削弱可读性。''',diagram=D('components','地服可用性与显示状态',['在地面','飞机静止','未连接推出','服务可用性','各服务状态','按钮外观与动作'],[(0,3,'必要条件'),(1,3,'必要条件'),(2,3,'必要条件'),(3,5,'控制可操作性'),(4,5,'控制状态表达')]),table=T('状态|语义|交互表现','HIDDEN|当前配置不显示|无按钮\nDISABLED|当前不可操作|弱化且禁用\nINACTIVE|未请求|可发起\nCALLED|已呼叫|等待反馈\nACTIVE|服务活动|可释放\nRELEASED|正在离开|等待结束')),
P('命令发送与反馈读取','''舱门、廊桥、行李车等通过 K: 事件发送命令；GPU 使用类型化事件总线 gpu_toggle；ASU 则写入本地变量。服务页面没有把所有设备强行统一为同一种 SimVar 写入，适配时必须保留这些调用方式的差别。

命令和反馈之间存在时间差。发出 TOGGLE_AIRCRAFT_EXIT 只说明请求切换指定舱门，不等于 INTERACTIVE POINT OPEN 已达到完全打开。原生页面观察后者更新状态，这是一种请求与观测分离的控制结构。

开发宿主能接收这些接口调用，但没有完整机场车辆调度与动画执行环境。当前画面的状态变化只适合说明交互协议；真实接入时需要将命令映射与观测映射分别实现。''',diagram=D('sequence','设备请求与宿主反馈的分离',['地服按钮','命令接口','运行宿主','状态订阅'],[(0,1,'发送服务命令'),(1,2,'请求动作'),(2,3,'设备状态更新'),(3,0,'更新按钮表现')]),table=T('服务类别|命令出口|主要观测','舱门|TOGGLE_AIRCRAFT_EXIT|INTERACTIVE POINT OPEN\n廊桥|TOGGLE_JETWAY|相关舱门与状态\n行李车|REQUEST_LUGGAGE|服务按钮状态\nGPU|gpu_toggle 事件|EXT_PWR_AVAIL\nASU|ASU_TURNED_ON 写入|同名变量读取')),
P('复杂服务的过渡状态','''廊桥、梯车、行李车和配餐车存在过渡过程。handleComplexService 在 INACTIVE 时进入 CALLED；如果相关舱门已经打开，使用定时器使按钮随后进入 ACTIVE，因为舱门不再变化，原来的观察回调不会再次触发。

在 CALLED 时再次点击表示取消。源码先暂时禁用按钮，延迟后恢复 INACTIVE，避免取消过程中连续点击使界面请求互相覆盖。活动服务的释放也有独立状态，不能用简单的布尔开关完整表达。

这些定时器是页面协调机制，不是设备确认协议。远端连接若具有明确 accepted、running、completed 回执，应以服务端状态驱动为主，同时保留超时提示处理丢失反馈。''',diagram=D('state','复杂服务按钮的主要生命周期',['INACTIVE','CALLED','ACTIVE','RELEASED','DISABLED'],[(0,1,'呼叫'),(1,2,'状态或延时反馈'),(2,3,'释放'),(3,0,'结束'),(1,4,'取消呼叫'),(4,0,'延时恢复')]),table=T('情况|当前处理|设计含义','舱门已打开再呼叫|5 秒后更新活动状态|补足无变量变化的情形\n呼叫中取消|短暂禁用，5.5 秒后恢复|限制重复请求\n正在释放|不接受再次点击|保持过渡一致性')),
P('地面变化与本地计划的关联','''原生燃油与载重操作可能改变确认后的目标，而本地参考结果仍保留旧输入。集成层通过 local-ground-change 通知本地状态。状态层设置 groundChanged 后，结果页显示变化原因，并关闭旧结果的当前报告出口。

当前“读取地面目标”专门读取燃油目标变量，不能被解释为自动读取所有客舱分布、重心与货物变化。用户改变载荷后仍需要回到工作台核对总量计划；交互提示采用“核对并重新确认”的含义。

这个接口建立了变化提示关系，而没有形成双向自动覆盖。原因是地面页可能只改变一个目标，直接覆盖完整 Flight 会丢失未编辑的计划上下文。''',diagram=D('sequence','地面目标变化使旧结果退出当前状态',['地面页面','集成事件','本地 State','结果页面'],[(0,1,'目标发生变化'),(1,2,'local-ground-change'),(2,2,'groundChanged = true'),(2,3,'当前结果失效'),(3,0,'提示核对计划')]),table=T('操作|本地响应|用户后续处理','更改燃油目标|标记地面变化|读取目标、确认、重算\n更改载重目标|标记地面变化|核对工作台载荷\n仅打开地面页|不等于修改|继续查看\n重新确认航班|建立新一致基准|按新输入计算')) ,refs=['EFB','L-S','L-B','GND'])
S(c,'登机、推出与地服协同',
P('登机目标与过程显示','''登机页将目标座位集合与当前集合并列使用。启动登机后，实际进度应由运行环境逐步更新；暂停或停止改变过程控制标志，而目标集合仍可保留。GSX 执行状态也参与页面编辑许可判断。

卸客操作先弹出确认框，再把目标人数与货物清零，稍后启动过程。该顺序使过程开始时已有明确的零目标，而不是边卸客边构造目标。正在运行时，同一入口用于停止当前过程。

本地浏览器主要提供目标设置和过程控件展示。页面中的时间估计和进度不能证明真实旅客登离机模型已在浏览器中执行。''',diagram=D('state','登机过程与目标的关系',['目标已设置','过程进行中','过程已停止','目标达到','卸客目标为零'],[(0,1,'开始'),(1,2,'停止'),(2,1,'继续'),(1,3,'宿主进度达到目标'),(3,4,'确认卸客'),(4,1,'启动卸客')]),table=T('变量类别|作用|所属层','目标人数及货物|定义终点|配载目标\nboardingStarted|启动或停止|过程控制\n当前位图及货物|表示进度|宿主状态\nGSX 状态|外部服务执行中判断|外部集成')),
P('推出页面的控制边界','''推出页面属于地面操作入口，向运行环境提交推出相关控制，并显示牵引连接及方向等状态。它与燃油、登机具有共同的“请求—状态”模式，但不参与 Flight 的质量计算公式。

一般地服可用性判断明确排除了已连接推出的情况，说明推出状态会影响其他页面的动作许可。设计上这类跨模块条件应由统一宿主状态提供，不宜由页面互相读取按钮颜色推断。

本地运行保持原生页面和控件结构，便于理解操作布置。与 PBNVDT 的真实牵引、位置和速度控制尚无连接，书中不把界面按钮存在作为运动仿真已经完成的证据。''',diagram=D('components','推出状态对地服动作的影响',['推出操作页','运行宿主','Pushback Attached','一般地服页','动作许可'],[(0,1,'发出推出请求'),(1,2,'连接状态'),(2,4,'影响许可'),(4,3,'启用或禁用')]),table=T('信息|来源|用途','推出控制请求|页面交互|请求宿主执行\n牵引连接状态|宿主读取|地服互斥条件\n飞机静止状态|宿主读取|服务许可\n飞机位置与运动|真实运行环境|当前浏览器未模拟完整运动')),
P('地面模块的依赖结构','''载重、燃油、服务和推出并不是单一顺序流水线。燃油和载重可分别设置目标，服务页面控制舱门与设备，推出状态则约束部分服务。它们通过宿主状态、配置和本地计划共享背景信息。

这种结构避免一个页面成为其他页面的调用中心。Ground 上层容器负责导航与公共属性，各专业页面负责自己的目标和动作。机型差异通过组件与配置选择体现，例如 A330 油箱图和宽体客舱图。

将来更换宿主时，可以保持页面结构并替换状态和命令适配。适配必须提供单位、时效与失败语义，不能只实现相同变量名称而忽略其业务含义。''',diagram=D('components','地面模块的共同依赖',['Ground 导航','燃油页','载重页','服务及推出页','机型配置','宿主状态与命令'],[(0,1,'页面选择'),(0,2,'页面选择'),(0,3,'页面选择'),(4,2,'客舱与容量'),(5,1,'油量和加油控制'),(5,3,'设备与运动状态')]),table=T('共性|集中位置|专业差异','页面选择|Ground 容器|各页交互布局\n机型身份|AircraftContext / 配置|A330 专用图形\n宿主数据|变量与事件接口|不同命令族\n本地一致性|地面变化事件|读取目标的范围')),
P('本地表现与真实接入的接口分工','''浏览器宿主的任务是使原生页面能够加载、读取示例状态并接受受控交互。真实运行环境则需要持续发布油量、座位占用、设备和运动状态，并确认命令执行。二者可共享接口名称，但具备不同的运行责任。

当前交付的地面模块用于界面验证、流程演示与软件设计研究。完整仿真连接的接口设计，应让每个数据项同时携带来源、采样时刻和质量标记；执行命令有独立标识，便于把按钮请求与后端回执关联。

这样，界面可以分别表达“请求已发出”“状态尚未更新”“设备已到位”，避免网络延迟时直接显示成功。该部分是扩展结构，尚未变更当前后端。''',diagram=D('entity','扩展设计：地面命令与状态回执',[['GroundCommand','commandId','action / target','createdAt'],['GroundSnapshot','revision / sampledAt','fuel / payload','services / pushback'],['CommandReceipt','commandId','accepted / status','reason']],[(0,2,'命令对应回执'),(1,2,'状态版本支持核对')]),table=T('当前职责|扩展后端职责|界面保持的职责','保存演示变量|发布真实状态快照|显示当前与目标\n接受接口调用|执行与拒绝命令|表达请求和失败\n发出变化提示|维护状态版本|使旧参考结果失效')) ,refs=['EFB','L-H','L-S','GND'])

c=C(10,'起飞参考计算模块详细设计','第二篇  分模块详细设计')
S(c,'计算职责与结果结构',
P('计算内核的功能范围','''本地起飞页围绕航班重量和源码 V2 表形成可追溯参考。calculate 是纯输入驱动的函数，接收 Flight，读取固定资料包，返回 Result。它不访问天气网站、不读取可变页面控件，也不直接写入飞机控制系统。

内核同时提供气压高度、风分量和有效 TORA 等辅助量。这些量用于解释输入环境，目前没有进入 V2 修正公式。页面把“辅助量已计算”与“性能修正已建立”分开呈现，防止从同屏出现推断不存在的计算关系。

Headwind 当前机型入口的完整起飞性能实现为 null。本地参考模块是独立扩展，不能把原生性能页面或源码速度表描述为完整起飞性能包。''',diagram=D('context','参考计算内核的输入与输出',['Flight 输入','calculate 内核','固定资料包','质量及环境辅助量','Result 参考结果'],[(0,1,'完整输入'),(2,1,'表格和版本'),(1,3,'直接派生'),(1,4,'状态与参考值')]),table=T('功能|当前结果|数据依据','重量一致性|载荷、ZFW、TOW|航班输入\n风与气压辅助量|数值及单位|通用公式\nV2 参考|表内线性插值|固定源码表\nV1、VR、FLEX|不提供|当前无完整模型\n距离及限制重量|不提供|当前无完整模型')),
P('Result 对象的语义','''Result 同时保存计算时刻、输入快照、资料版本、内核版本、签名和状态。数值只是结果的一部分；来源与输入身份决定用户何时能够继续使用它。input 通过 structuredClone 固定下来，不随草稿对象后续修改而变化。

所有结果先按 invalid 创建，辅助数值初始化为 null。格式和业务校验通过后，才填充重量和环境数据。若资料范围不支持，状态变为 unsupported，并保留已能可靠计算的辅助量。完成插值后才得到 reference-only。

null 表示该值没有生成，与数值零不同。例如无风时侧风应为 0；无效输入导致风未计算时应为空值。页面必须保持这个区别。''',diagram=D('entity','Result 的三个信息组',[['结果身份','at / signature','profileVersion','engineVersion'],['计算输入','input 快照','weights','来源字段'],['计算输出','status / errors','v2 / 辅助量','unsupported 清单']],[(0,1,'标识本次输入'),(1,2,'形成可解释输出')]),table=T('状态|数值可用性|页面含义','invalid|主要量为 null|修正输入\nunsupported|辅助量可能存在，V2 为空|条件超出资料支持\nreference-only|包含 V2 参考|限于当前源码表算术')),
P('校验、适用性与插值顺序','''计算先执行 validate，保证对象结构、数字、范围和质量关系成立。然后求质量、气压高度、风分量与有效距离，再判断表格重量范围、跑道条件以及防冰和引气状态。任何适用性检查失败都提前返回。

重量范围先于跑道及系统配置判断，因此多个条件同时不支持时，当前函数首先返回最先遇到的条件。它不是一次列出所有模型适用性问题的规则引擎。输入校验的 errors 集合与适用性阶段的提前返回具有不同机制。

顺序清晰的好处是错误原因可以对应具体阶段。扩展修正模型时，应在适用性判断与插值之间明确加入修正数据，而不是仅删除拒绝条件。''',diagram=D('pipeline','calculate 的执行阶段',['结构及业务校验','重量和环境派生','重量范围判断','跑道与系统条件','表内插值','封装参考结果']),table=T('阶段|失败状态|仍可保留的内容','基础校验|invalid|原始输入及版本\n重量表范围|unsupported|质量和环境辅助量\n跑道 / 防冰 / 引气|unsupported|质量和环境辅助量\n表内插值完成|reference-only|输入与全部已支持输出')),
P('结果与界面的解耦','''计算函数返回数据，不负责决定按钮颜色、报告文件名或历史排序。状态层判断是否允许执行，页面负责格式化显示，报告层负责导出。这样同一内核可以通过单元调用验证算术，也可以被当前 React 页面使用。

显示 V2 时保留原始插值数值，并给出向上取整的展示值。取整不是资料表修正，更不会反过来修改 Result.v2。重量、气压和风分量也应由显示层决定小数位，避免为了界面美观损失内部信息。

当前结果的有效性还依赖确认签名和地面变化标记，因此不能仅凭 Result.status 为 reference-only 就开启导出。''',diagram=D('components','计算、状态与呈现分工',['Flight + profile','calculate','Result','状态层 currentResult','页面格式化','报告与历史'],[(0,1,'固定输入'),(1,2,'生成'),(2,3,'检查当前有效性'),(3,4,'显示'),(3,5,'允许出口')]),table=T('层次|负责事项|保留的信息','内核|算术与适用性|原始数值\n状态层|确认与时效|当前输入身份\n页面|单位和小数显示|数值含义\n报告|固定输入与结果|可追溯快照')) ,refs=['L-F','L-D','L-S','EFB'])
S(c,'质量模型与结构约束',
P('重量链条的正向计算','''weights 采用明确的质量组成：旅客人体和行李按人数乘平均质量，额外货物单独相加，得到 payload；加上 OEW 得到 ZFW；再加停机坪燃油得到 ramp；扣除滑行耗油得到 TOW。

每一个派生量都有不同时间或组成含义。ZFW 不含可用燃油，停机坪重量对应滑行耗油前，TOW 对应扣除计划滑行耗油后的起飞计划。计算中不引入航程耗油或着陆燃油，因为 Flight 尚未保存这些项目。

把公式集中为 weights，可以确保工作台卡片、兼容航班数据、计算结果和报告中的重量由相同规则生成。''',diagram=D('formula','本地计划的质量链条',[['载荷','payload = pax × (paxKg + bagKg) + freightKg'],['零油重','ZFW = OEW + payload'],['起飞重量','TOW = ZFW + rampFuel − taxiFuel']]),table=T('质量项目|是否包含燃油|主要用途','payload|否|载荷构成\nZFW|否|结构零油重检查\nramp weight|含停机坪燃油|初始全重\nTOW|含起飞燃油|V2 表格自变量')),
P('完整数值演算','''样例以 250 人、每人 80 kg、平均行李 24 kg 和额外货物 2000 kg 构造计划。旅客人体质量为 20000 kg，行李为 6000 kg，载荷合计为 28000 kg。固定 OEW 127000 kg，因此 ZFW 为 155000 kg。

停机坪燃油 30000 kg 使停机坪重量达到 185000 kg。滑行耗油 500 kg，计划起飞燃油为 29500 kg，TOW 为 184500 kg。这个 TOW 是后续速度插值的唯一质量自变量。

读者可以沿着每一步追溯数值来源。若最终 TOW 不一致，应先检查平均行李是否已经包含在货舱总量中，避免把行李重复加入 freightKg。''',table=T('步骤|算式|结果 / kg','人体质量|250 × 80|20000\n行李质量|250 × 24|6000\n载荷合计|20000 + 6000 + 2000|28000\n零油重|127000 + 28000|155000\n停机坪重量|155000 + 30000|185000\n起飞重量|185000 − 500|184500'),diagram=D('pipeline','样例质量的逐层累加',['人及行李 26000','加货物得 28000','加 OEW 得 155000','加油得 185000','扣滑行油 500','TOW 184500'])) ,
P('结构上限与表格上限','''当前资料包的最大零油重为 181000 kg，结构最大起飞重量为 251000 kg；V2 源码表的质量范围却是 130000～250000 kg。结构检查通过不代表速度表一定覆盖，因此两类限制分别执行。

例如 TOW 为 250500 kg 时，可能没有超过结构配置值，但已经超过表格最后一个节点。计算返回 unsupported，不把 250 吨点的速度直接延伸到 250.5 吨。反之，低于表格最小质量也禁止外推。

这些结构数值与固定资料配置绑定。更换机型变体、发动机或重量选装需要独立配置身份和来源，不应通过临时改一个常量继续沿用原结果。''',diagram=D('lanes','结构合法与模型覆盖分别判断',[['结构','ZFW ≤ 181 t','TOW ≤ 251 t','输入合法'],['资料','TOW ≥ 130 t','TOW ≤ 250 t','允许表内插值']]),table=T('TOW 例子|结构检查|速度表覆盖','129 t|可能通过其他质量关系|低于表格\n184.5 t|通过|覆盖\n250 t|通过|最后节点\n250.5 t|可通过|超出范围\n252 t|失败|不进入插值')),
P('输入敏感性与变化解释','''在人数及平均质量不变时，增加 1000 kg 燃油使 TOW 增加 1000 kg；增加 10 名旅客，在每人及行李合计 104 kg 的样例中使 TOW 增加 1040 kg；增加滑行耗油则等量减少 TOW。

质量关系是线性的，速度参考对质量的响应却由所在表格区间决定。同样增加一吨，在平坦区间可能不改变 V2，在上升区间会按该段斜率增加。不能用一个全局“每吨增加多少节”的系数代替原表。

敏感性说明有助于解释用户改动后的结果差异，但不是重量优化器。系统没有搜索限制重量，也没有在多种跑道约束间求最优起飞方案。''',diagram=D('formula','重量对输入的局部响应',[['燃油与货物','ΔTOW = ΔrampFuel + Δfreight'],['人数','ΔTOW = Δpax × (paxKg + bagKg)'],['滑行耗油','ΔTOW = −ΔtaxiFuel']]),table=T('单项改动|样例 TOW 变化|新 TOW','燃油 +1000 kg|+1000 kg|185500 kg\n旅客 +10 人|+1040 kg|185540 kg\n滑行油 +200 kg|−200 kg|184300 kg')) ,refs=['L-F','L-D','L-S'])
S(c,'速度表结构与插值算法',
P('资料表的离散节点','''速度资料以襟翼配置作为第一维，以质量节点作为第二维。三个配置各有 13 个数值，质量从 130000 kg 起每隔 10000 kg 一个节点，最后为 250000 kg。资料包同时保存单位、来源提交与已知问题。

数组索引不是任意编号，而是由固定起点和步长定义的坐标。程序应同时解释 massMin、step 和数组长度；只复制数组而丢失质量坐标，会使同一组速度被错误地用于别的重量。

图中保留原表形状，包括平坦段、下降段和 CONF 3 的突变。资料工程应忠实呈现现有数据，不能为了曲线更平滑而悄悄改变来源值。''',diagram=D('plot','源码 V2 表三种配置的离散趋势',[],x=list(range(130,251,10)),series=[{'name':'CONF 1','y':[146,146,146,145,145,149,153,157,161,164,164,167,168]},{'name':'CONF 2','y':[143,143,143,143,142,142,146,150,154,157,161,165,165]},{'name':'CONF 3','y':[141,141,141,140,140,139,141,145,148,151,166,166,166]}],xlabel='起飞重量 / t',ylabel='V2 / kt'),table=T('元数据|值|作用','起点 / 步长|130000 / 10000 kg|定义索引坐标\n节点数|13|覆盖至 250000 kg\n速度单位|kt CAS|说明速度类型\n配置维度|1、2、3|选择对应数组')),
P('区间定位与线性组合','''先把质量转换为连续索引 i，再取 floor(i) 得到下节点 lo；上节点 hi 为 lo+1，但不超过最后索引 12。小数部分 i−lo 是在该区间中的位置，线性组合两个速度即可得到参考值。

在质量恰好等于节点时，小数部分为零，结果严格等于节点值。最后节点的 lo 与 hi 都为 12，因此无需访问不存在的第 14 个数值。这个边界处理建立在此前已拒绝超范围质量的基础上。

算法采用标准浮点数。当前输入规模与显示精度适合此类算术，但显示层应集中格式化，以避免把二进制浮点尾数直接放到用户界面。''',diagram=D('formula','质量索引与插值表达式',[['区间定位','i = (TOW − 130000) / 10000；lo = floor(i)'],['上节点','hi = min(12, lo + 1)；α = i − lo'],['参考速度','V2 = table[lo] + α × (table[hi] − table[lo])']]),table=T('质量|连续索引|节点选择','180000 kg|5.0|5 和 6，α = 0\n184500 kg|5.45|5 和 6，α = 0.45\n250000 kg|12.0|12 和 12，α = 0')),
P('184.5 吨参考结果的形成','''样例 TOW 为 184500 kg，对应索引 5.45。CONF 1 在 180 吨与 190 吨分别为 149 kt 和 153 kt，差值为 4 kt，区间位置 0.45，因此结果为 149+4×0.45=150.8 kt。

若只改变襟翼配置，CONF 2 两端为 142 和 146，得到 143.8 kt；CONF 3 两端为 139 和 141，得到 139.9 kt。三组结果来自三个数组，不能从 CONF 1 减去一个固定修正值推导。

页面展示的向上取整参考分别为 151、144、140 kt。内部 Result 仍保留 150.8、143.8、139.9。报告同时显示原值和取整值，使读者能够复算。''',table=T('配置|区间端点 / kt|184.5 t 插值 / kt','CONF 1|149 → 153|150.8\nCONF 2|142 → 146|143.8\nCONF 3|139 → 141|139.9'),diagram=D('plot','180～190 吨区间中的样例位置',[],x=[180,184.5,190],series=[{'name':'CONF 1','y':[149,150.8,153]},{'name':'CONF 2','y':[142,143.8,146]},{'name':'CONF 3','y':[139,139.9,141]}],xlabel='TOW / t',ylabel='V2 / kt')),
P('异常节点与资料版本','''CONF 3 在 220 吨为 151 kt，在 230 吨为 166 kt，十吨区间增加 15 kt。当前版本保留这一源码特征，并把它列入 knownIssues。225 吨的线性结果为 158.5 kt，这只是对现有节点的数学插值。

不能因为数值异常就猜测一个更合理节点覆盖原值，也不能因为代码可算就证明该节点具有真实运行适用性。资料修订需要可说明的原始来源、机型构型和适用条件，并产生新的 profileVersion。

版本更改后，输入签名也随资料包变化。旧历史仍可说明过去使用了什么数据，但不自动成为新资料下的当前结果。''',diagram=D('plot','CONF 3 的已知突变区间',[],x=[210,220,225,230,240],series=[{'name':'保留源码节点及线性中点','y':[148,151,158.5,166,166]}],xlabel='TOW / t',ylabel='V2 / kt'),table=T('处理方式|当前采用情况|理由','保留原值并说明|采用|可追溯来源\n静默平滑|不采用|会改变资料含义\n新资料替换|需独立版本|保留新旧身份\n扩大适用声明|不随算术自动扩大|来源仍需确认')) ,refs=['L-F','L-D','SPD'])
S(c,'环境辅助量与跑道信息',
P('气压高度近似换算','''气压高度由跑道标高和 QNH 共同决定。公式以 1013.25 hPa 为基准，使用固定常数和幂指数计算压力偏差对应的高度增量，再与跑道标高相加。输入单位为 ft 与 hPa，输出为 ft。

当 QNH 为标准值时，幂项为 1，修正项为零，气压高度等于输入标高。气压低于标准值时修正为正，高于标准值时修正为负。这个方向性有助于理解数值，而无需把近似公式误读为实时大气剖面模型。

当前 V2 表没有按气压高度建立维度，因此该结果只作为环境辅助显示。页面出现气压高度并不意味着已经完成高温高原性能修正。''',diagram=D('formula','当前采用的气压高度公式',[['压力修正','Δh = 145442.15 × [1 − (QNH / 1013.25)^0.190263]'],['气压高度','PA_ft = elevation_ft + Δh'],['标准气压','QNH = 1013.25 hPa → PA = elevation']]),table=T('输入|单位|角色','elevationFt|ft|跑道标高\nqnh|hPa|用户录入气压\npressureAltitudeFt|ft|派生辅助量\nOAT|°C|保存环境输入，当前不修正 V2')),
P('顺风、逆风与侧风投影','''算法取风向与跑道方向之差作为角度，并从度转换为弧度。风速乘余弦得到纵向分量，乘正弦得到带符号侧向分量。风向表示风的来向，因此差角为零时得到正的逆风分量。

正负号的含义应在显示中明确。headwindKt 为负时代表顺风；crosswindKt 的符号来自当前方向约定。若界面只需要侧风大小，应显示绝对值，但不能在结果对象中丢掉原符号。

例如跑道方向 10°、风向 40°、风速 20 kt，差角为 30°，逆风约 17.32 kt，带符号侧风为 10 kt。这里的风分解没有施加起飞性能中的风折算系数。''',diagram=D('formula','风向向跑道坐标的投影',[['角度转换','θ = (windDir − runwayHeading) × π / 180'],['纵向分量','headwind = windSpeed × cos(θ)'],['侧向分量','crosswind = windSpeed × sin(θ)']]),table=T('差角|纵向分量|侧向分量','0°|全部逆风|0\n90°|约 0|正侧风\n180°|全部顺风|约 0\n−90°|约 0|负侧风')),
P('声明距离与入口扣减','''Flight 保存 TORA、TODA 和 ASDA，用于保留跑道资料与检查距离关系。当前只计算 effectiveTora=TORA−intersection，表示按用户给定扣减得到的剩余起飞滑跑可用距离。

effectiveTora 不是起飞所需距离。模块没有计算加速停止距离、起飞距离或障碍物限制，也没有将该值与某个所需距离相除得到合格判断。TODA 与 ASDA 当前也没有形成独立的性能限制求解。

来源文本随跑道资料一同保存。这样报告能够说明数值来自手工示例或用户资料，避免把人工录入的距离当作已经同步的机场数据库记录。''',diagram=D('formula','当前已实现的距离派生',[['声明资料','TODA ≥ TORA；ASDA ≥ TORA'],['入口扣减','0 ≤ intersection < TORA'],['剩余滑跑距离','effectiveTora = TORA − intersection']]),table=T('数据项|本地用途|未包含的推导','TORA|合法性与扣减|起飞所需距离\nTODA|关系校验及保存|起飞距离余量\nASDA|关系校验及保存|加速停止余量\n坡度|录入及保存|V2 或距离修正\n来源|报告追溯|权威性自动认证')) ,refs=['L-F','L-D'])
S(c,'结果生命周期与输出设计',
P('计算结果的当前性','''currentResult 将计算状态与业务状态合并判断。结果必须为 reference-only，结果签名、当前输入签名和 confirmed 必须一致，同时 groundChanged 为 false。只有满足这些条件，结果才可以作为当前报告和历史归档的来源。

这个判断比按钮禁用更重要。页面展示可能延迟一个刷新周期，或某入口没有及时更新外观，但状态函数仍会拒绝不合格出口。业务规则因此集中在可复用状态层，减少界面分支间的差异。

旧 Result 可以继续保留供比较。保留旧值与允许继续使用旧值是两件事：失效提示明确标记它已经不能代表现在的输入。''',diagram=D('components','当前结果资格的合取条件',['reference-only','结果签名匹配','确认签名匹配','地面未变化','currentResult','报告及历史出口'],[(0,4,'状态条件'),(1,4,'输入条件'),(2,4,'确认条件'),(3,4,'地面条件'),(4,5,'统一授权')]),table=T('变化|结果对象是否保留|当前出口','修改输入|可保留|关闭\n更改地面目标|可保留|关闭\n恢复历史输入|历史仍保留|需重新确认与计算\n重算成功|替换最近结果|符合条件时开启')),
P('历史快照与重新使用','''历史保存的是 Result，而不是只保存一个速度数字。每条记录具备输入、时间和版本，所以恢复动作能够回到当时的航班条件。列表保留最近 20 条，最新记录在前，限制浏览器存储增长。

恢复历史读取 input 并进入正常的 loadFlight/editFlight 路径。历史结果不会直接成为当前确认；用户核对后重新确认，再使用当前资料包计算。这样旧版本输入可以复用，同时避免沿用失去适用基础的旧计算。

历史记录适合本机工作回看，不承担多人审批、不可抵赖审计或长期档案服务。需要跨机保留时，应使用 JSON 输入文件与 HTML 结果报告分别保存。''',diagram=D('sequence','历史恢复重新建立当前计算',['历史列表','loadFlight','确认动作','计算内核'],[(0,1,'选择记录的 input'),(1,1,'撤销当前确认'),(1,2,'用户核对后确认'),(2,3,'按当前资料计算'),(3,0,'需要时保存新记录')]),table=T('内容|历史快照|JSON 航班文件','输入字段|包含|包含\n计算结果|包含|不包含\n版本与时间|包含|仅航班自身字段\n用途|本机回看|输入交换与备份')),
P('报告内容与可读性','''HTML 报告以当前有效结果为唯一入口，包含航班身份、重量、跑道和天气、V2 原值及取整展示、资料与内核版本、未支持能力以及完整输入 JSON。报告是固定快照，生成后不再随着界面修改自动变化。

动态文本在写入 HTML 前经过转义，避免航路或来源文字被解释为标签。下载使用 Blob 和临时对象地址，完成触发后撤销地址；打印通过独立窗口提供浏览器打印入口。弹窗受阻时仍可下载 HTML 保存。

报告的用途是解释本次软件参考计算。版面应把计算状态与数据来源放在数值附近，使报告脱离软件页面后仍能被正确理解。''',diagram=D('pipeline','当前结果到独立报告',['currentResult 检查','读取固定输入快照','格式化与文本转义','生成 HTML','下载或打印','保留版本与来源']),table=T('报告区域|内容|阅读作用','摘要|航班及计算时间|识别本次记录\n输入|质量、跑道、天气|复算依据\n结果|原值及取整值|解释数值\n模型信息|版本、来源、能力边界|说明适用范围\n完整 JSON|输入快照|机器可读留存')) ,refs=['L-F','L-S','L-U','L-D'])
